INSERT INTO public.exercises
  (name,category,equipment,description,video_url,is_active,body_area,is_rehab,created_by)
SELECT c.name,c.category,c.equipment,c.description,c.video_url,c.is_active,c.body_area,c.is_rehab,NULL
FROM catalogue c
WHERE NOT EXISTS (
  SELECT 1 FROM public.exercises e
  WHERE lower(trim(e.name))=lower(trim(c.name))
);
